import base64, hashlib, json, re
from pathlib import Path
root = Path('products/distribution/sqlite-curated-tools')
paths = {key: root / 'raw' / filename for key, filename in {'readme': 'readme.json', 'profile': 'community-profile.json', 'pulls': 'recent-closed-pull-requests.json'}.items()}
raw = {key: path.read_bytes() for key, path in paths.items()}
readme = base64.b64decode(json.loads(raw['readme'])['content']).decode('utf-8')
profile = json.loads(raw['profile'])
pulls = json.loads(raw['pulls'])
terms = re.compile(r'contribut|pull request|diagnos|debug|explain|inspect|visuali[sz]|playground|online|affiliat|AI.generated', re.I)
section = ''
lines = []
for number, line in enumerate(readme.splitlines(), 1):
    if line.startswith('#'):
        section = line
    if terms.search(line):
        lines.append({'line': number, 'section': section, 'text': line})
merged = [{key: pr.get(key) for key in ('number', 'title', 'html_url', 'merged_at')} for pr in pulls if pr.get('merged_at')]
files = profile.get('files') or {}
policy_links = {key: info.get('html_url') for key, info in files.items() if isinstance(info, dict) and key in ('contributing', 'pull_request_template', 'code_of_conduct')}
result = {'source_sha256': {key: hashlib.sha256(data).hexdigest() for key, data in raw.items()}, 'readme_matches': lines, 'merged_sample': merged, 'policy_links': policy_links, 'limits': 'Merged titles and README excerpts are pointers. Verify actual changed lines and policy text in context. Unlisted policy links do not establish permission.'}
out = root / 'director-placement-comparables.json'
out.write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
saved = json.loads(out.read_text(encoding='utf-8'))
assert saved == result
print(json.dumps({'artifact': str(out), 'merged': len(merged), 'policy_links': policy_links, 'readme_matches': len(lines)}))
